    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C35", "C45"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the exact query molecule.",
    "AZD0837 differs from the query in the amidoxime O-substituent (methoxy vs hydroxy) and in the acyl/ester region, so the transfer is analog-based rather than identical-molecule evidence.",
    "No query-specific data on first-pass metabolism, efflux, solubility, or prodrug conversion are available.",
    "The lower end of the AZD0837 F range (22%) is close to the 20% threshold.",
    "L2 active-metabolite data (perindoprilat F 19±7% in young subjects) add uncertainty about prodrug conversion, but the parent-compound endpoint remains supported."
  ],
  "decision_summary": "Prediction remains high (F ≥ 20%): the closest structural context, AZD0837, has measured absolute oral bioavailability of 22–55% in humans and shares the benzyl amidoxime–azetidine amide core; L2 confirms this range and adds multiple high parent-F reports for the ester prodrug perindopril. The low perindoprilat F in young subjects is context for prodrug conversion but does not overturn the parent-compound endpoint. Confidence stays moderate because the evidence is analog-based and the lower bound is near the threshold."
}

